import React, { createContext, useContext, useState, useRef, useCallback, ReactNode, useEffect, useMemo } from 'react';
import useLocalStorage from '../hooks/useLocalStorage';
import { Emotion, ActivityLog, EmotionLog, ConnectionStatus, SUPPORTED_EMOTIONS, EquippedItems } from '../types';
import { SHOP_ITEMS } from '../constants';

// For Azure, we typically use a Web App or Function with WebSockets or SignalR.
// This implementation assumes a standard WebSocket interface provided by an Azure App Service.
const AZURE_WS_URL = 'wss://pelioscope-backend.azurewebsites.net/ws'; 

type Theme = 'light' | 'dark';

interface AppContextType {
  companionName: string;
  setCompanionName: (name: string) => void;
  userName: string;
  setUserName: (name: string) => void;
  userPin: string;
  setUserPin: (pin: string) => void;
  currentEmotion: Emotion;
  currentConfidence: number | null;
  lastUpdate: number | null;
  emotionHistory: EmotionLog[];
  activityHistory: ActivityLog[];
  addActivityLog: (activityName: ActivityLog['activityName']) => void;
  clearHistory: () => void;
  connectionStatus: ConnectionStatus;
  connectionError: string | null;
  toggleSystemState: (state: 'start' | 'stop') => void;
  isSystemRunning: boolean;
  theme: Theme;
  toggleTheme: () => void;

  // Hygiene & Hunger
  lastShowerTime: number;
  setLastShowerTime: (time: number) => void;
  isPeliDirty: boolean;
  hungerLevel: number; // 0-100
  feedPeli: (amount: number) => void;
  isPeliHungry: boolean;

  // Economy & Shop
  drachma: number;
  earnDrachma: (amount: number) => void;
  spendDrachma: (amount: number) => boolean; // returns true if successful
  inventory: string[]; // List of item IDs
  equippedItems: EquippedItems;
  buyItem: (itemId: string, price: number) => boolean;
  equipItem: (category: keyof EquippedItems, itemId: string | null) => void;
  consumeItem: (itemId: string) => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [companionName, setCompanionName] = useLocalStorage('companionName', 'PELI');
  const [userName, setUserName] = useLocalStorage('userName', '');
  const [userPin, setUserPin] = useLocalStorage('userPin', ''); 

  const [activityHistory, setActivityHistory] = useLocalStorage<ActivityLog[]>('activityHistory', []);
  const [emotionHistory, setEmotionHistory] = useLocalStorage<EmotionLog[]>('emotionHistory', []);
  const [theme, setTheme] = useLocalStorage<Theme>('theme', 'light');

  const [lastShowerTime, setLastShowerTime] = useLocalStorage<number>('lastShowerTime', 0);
  const [hungerLevel, setHungerLevel] = useLocalStorage<number>('hungerLevel', 50); 
  const [lastHungerCalc, setLastHungerCalc] = useLocalStorage<number>('lastHungerCalc', Date.now());

  const [drachma, setDrachma] = useLocalStorage<number>('drachma', 1000);
  const [inventory, setInventory] = useLocalStorage<string[]>('inventory', []);
  const [equippedItems, setEquippedItems] = useLocalStorage<EquippedItems>('equippedItems', {
      hat: null,
      clothes: null,
  });

  const [currentEmotion, setCurrentEmotion] = useState<Emotion>('Happy');
  const [currentConfidence, setCurrentConfidence] = useState<number | null>(null);
  const [lastUpdate, setLastUpdate] = useState<number | null>(null);
  const [isSystemRunning, setIsSystemRunning] = useState<boolean>(false);

  const [connectionStatus, setConnectionStatus] = useState<ConnectionStatus>('connecting');
  const [connectionError, setConnectionError] = useState<string | null>(null);

  const socketRef = useRef<WebSocket | null>(null);

  // HUNGER DECAY LOGIC
  useEffect(() => {
    const calculateDecay = () => {
        const now = Date.now();
        const diff = now - lastHungerCalc;
        const msPerPoint = 72000; 
        const pointsLost = Math.floor(diff / msPerPoint);

        if (pointsLost > 0) {
            setHungerLevel(prev => Math.max(0, prev - pointsLost));
            setLastHungerCalc(now);
        }
    };
    calculateDecay();
    const interval = setInterval(calculateDecay, 60000);
    return () => clearInterval(interval);
  }, [lastHungerCalc, setHungerLevel, setLastHungerCalc]);

  const feedPeli = useCallback((amount: number) => {
      setHungerLevel(prev => Math.min(100, prev + amount));
  }, [setHungerLevel]);

  const isPeliHungry = useMemo(() => hungerLevel < 50, [hungerLevel]);
  const isPeliDirty = useMemo(() => (Date.now() - lastShowerTime) > (3 * 60 * 60 * 1000), [lastShowerTime]);

  // AZURE WEBSOCKET INTEGRATION
  const connectToAzure = useCallback(() => {
    if (socketRef.current) socketRef.current.close();

    setConnectionStatus('connecting');
    const socket = new WebSocket(AZURE_WS_URL);
    socketRef.current = socket;

    socket.onopen = () => {
      setConnectionStatus('connected');
      setConnectionError(null);
      // Request initial status from Azure server
      socket.send(JSON.stringify({ type: 'request_sync' }));
    };

    socket.onmessage = (event) => {
      try {
        const message = JSON.parse(event.data);

        // Handle Emotion Updates
        if (message.type === 'emotion_output') {
          const data = message.data;
          let label = data.label || data.emotion || '';
          let confidence = data.score || data.confidence || null;
          let timestamp = data.timestamp || Date.now();

          if (!label) return;

          const normalized = label.toString().toLowerCase().trim();
          const synonymMap: Record<string, Emotion> = {
            'happy': 'Happy', 'joy': 'Happy', 'excited': 'Happy',
            'sad': 'Sad', 'angry': 'Angry', 'mad': 'Mad',
            'fear': 'Fear', 'surprised': 'Surprised',
            'disgust': 'Disgust', 'neutral': 'Neutral'
          };

          let matched = synonymMap[normalized] || SUPPORTED_EMOTIONS.find(e => e.toLowerCase() === normalized);

          if (matched) {
            setCurrentEmotion(matched);
            setCurrentConfidence(confidence);
            setLastUpdate(timestamp);
            setEmotionHistory(prev => {
              if (prev.length === 0 || prev[0].emotion !== matched) {
                return [{ id: Date.now().toString(), emotion: matched!, detectedAt: Date.now() }, ...prev].slice(0, 100);
              }
              return prev;
            });
          }
        }

        // Handle System State Updates
        if (message.type === 'system_state') {
          setIsSystemRunning(message.state === 'start');
        }

      } catch (err) {
        console.error("Error parsing Azure message:", err);
      }
    };

    socket.onerror = (error) => {
      console.error("WebSocket Error:", error);
      setConnectionStatus('error');
      setConnectionError("Failed to connect to Azure server.");
    };

    socket.onclose = () => {
      setConnectionStatus('disconnected');
      // Exponential backoff or simple retry
      setTimeout(connectToAzure, 5000);
    };
  }, [setEmotionHistory]);

  useEffect(() => {
    connectToAzure();
    return () => {
      if (socketRef.current) socketRef.current.close();
    };
  }, [connectToAzure]);

  const toggleSystemState = useCallback((state: 'start' | 'stop') => {
    if (socketRef.current && socketRef.current.readyState === WebSocket.OPEN) {
      socketRef.current.send(JSON.stringify({
        type: 'set_state',
        state: state
      }));
      setIsSystemRunning(state === 'start');
    } else {
      setConnectionError("Not connected to Azure server.");
    }
  }, []);

  // Theme Logic
  useEffect(() => {
    const root = window.document.documentElement;
    if (theme === 'dark') root.classList.add('dark');
    else root.classList.remove('dark');
  }, [theme]);

  const toggleTheme = useCallback(() => setTheme(prev => prev === 'light' ? 'dark' : 'light'), [setTheme]);

  // Economy Logic
  const earnDrachma = useCallback((amount: number) => setDrachma(prev => prev + amount), [setDrachma]);
  const spendDrachma = useCallback((amount: number) => {
      if (drachma >= amount) { setDrachma(prev => prev - amount); return true; }
      return false;
  }, [drachma, setDrachma]);

  const buyItem = useCallback((itemId: string, price: number) => {
      const shopItem = SHOP_ITEMS.find(i => i.id === itemId);
      const isConsumable = shopItem?.category === 'food';
      const isOwned = inventory.includes(itemId);
      if (!isConsumable && isOwned) return true;
      if (drachma >= price) {
          setDrachma(prev => prev - price);
          setInventory(prev => [...prev, itemId]);
          return true;
      }
      return false;
  }, [drachma, inventory, setDrachma, setInventory]);

  const consumeItem = useCallback((itemId: string) => {
      setInventory(prev => {
          const idx = prev.indexOf(itemId);
          if (idx > -1) {
              const newInv = [...prev];
              newInv.splice(idx, 1);
              return newInv;
          }
          return prev;
      });
  }, [setInventory]);

  const equipItem = useCallback((category: keyof EquippedItems, itemId: string | null) => {
      setEquippedItems(prev => ({ ...prev, [category]: itemId }));
  }, [setEquippedItems]);

  const addActivityLog = useCallback((activityName: ActivityLog['activityName']) => {
    const newLog: ActivityLog = { id: Date.now().toString(), activityName, completedAt: Date.now() };
    setActivityHistory(prev => [newLog, ...prev]);
  }, [setActivityHistory]);

  const clearHistory = useCallback(() => {
    setActivityHistory([]);
    setEmotionHistory([]);
  }, [setActivityHistory, setEmotionHistory]);

  const contextValue: AppContextType = {
    companionName, setCompanionName, userName, setUserName, userPin, setUserPin,
    currentEmotion, currentConfidence, lastUpdate, emotionHistory, activityHistory,
    addActivityLog, clearHistory, connectionStatus, connectionError,
    toggleSystemState, isSystemRunning, theme, toggleTheme,
    lastShowerTime, setLastShowerTime, isPeliDirty, hungerLevel, feedPeli, isPeliHungry,
    drachma, earnDrachma, spendDrachma, inventory, equippedItems, buyItem, equipItem, consumeItem
  };

  return <AppContext.Provider value={contextValue}>{children}</AppContext.Provider>;
};

export const useAppContext = (): AppContextType => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useAppContext must be used within an AppProvider');
  return context;
};

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';
import { AppProvider } from './contexts/AppContext';

// The app connects to an Azure App Service via WebSockets 
// for real-time emotion telemetry.
const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <AppProvider>
      <App />
    </AppProvider>
  </React.StrictMode>
);

