import React, { useMemo } from 'react';
import { useAppContext } from '../contexts/AppContext';
import { EMOTION_DETAILS } from '../constants';
import { ConnectionStatus } from '../types';

const StatusBadge: React.FC<{ status: ConnectionStatus }> = ({ status }) => {
  const statusConfig = useMemo(() => {
    switch (status) {
      case 'connected':
        return { text: 'Azure Sync', color: 'bg-green-100 text-green-800', dotColor: 'bg-green-500' };
      case 'connecting':
        return { text: 'Connecting...', color: 'bg-yellow-100 text-yellow-800', dotColor: 'bg-yellow-500 animate-pulse' };
      case 'error':
        return { text: 'Server Error', color: 'bg-red-100 text-red-800', dotColor: 'bg-red-500' };
      default:
        return { text: 'Disconnected', color: 'bg-gray-100 text-gray-800', dotColor: 'bg-gray-400' };
    }
  }, [status]);

  return (
    <div className={`inline-flex items-center px-3 py-1 rounded-full text-sm font-medium ${statusConfig.color}`}>
      <span className={`w-2 h-2 mr-2 rounded-full ${statusConfig.dotColor}`}></span>
      {statusConfig.text}
    </div>
  );
};

const LiveTab: React.FC = () => {
  const { 
    currentEmotion, 
    connectionStatus, 
    connectionError, 
    toggleSystemState, 
    isSystemRunning,
    currentConfidence, 
    lastUpdate 
  } = useAppContext();

  const idleDetails = {
    emoji: '😴',
    color: 'text-gray-400 dark:text-gray-500',
    pulseColor: '#9ca3af'
  };

  const emotionDetails = isSystemRunning ? EMOTION_DETAILS[currentEmotion] : idleDetails;
  const displayLabel = isSystemRunning ? currentEmotion : 'Idle';

  const handleToggleSystem = () => {
    const newState = isSystemRunning ? 'stop' : 'start';
    toggleSystemState(newState);
  };

  const buttonText = isSystemRunning ? 'Stop Detection' : 'Start Detection';
  const buttonColor = isSystemRunning ? 'bg-red-500 hover:bg-red-600' : 'bg-indigo-500 hover:bg-indigo-600';

  return (
    <div className="flex flex-col items-center justify-center h-full p-4 text-center">
      <div className="absolute top-4">
        <StatusBadge status={connectionStatus} />
      </div>

      <div className="flex-grow flex flex-col items-center justify-center w-full">
        <div 
          className="relative flex items-center justify-center w-64 h-64 rounded-full transition-all duration-500"
        >
           <style>
            {`
              @keyframes pulse {
                0%, 100% { transform: scale(1); box-shadow: 0 0 0 0 var(--pulse-color); }
                50% { transform: scale(1.05); box-shadow: 0 0 20px 20px rgba(0,0,0,0); }
              }
              .animate-pulse-emotion {
                animation: pulse 2s infinite;
              }
            `}
          </style>
          <div 
            className={`absolute inset-0 rounded-full ${isSystemRunning ? 'animate-pulse-emotion' : ''}`}
            style={{ '--pulse-color': emotionDetails.pulseColor } as React.CSSProperties}
          ></div>
           <span
            className={`text-[120px] transition-colors duration-500 ${emotionDetails.color}`}
            style={{ textShadow: `0 4px 20px ${emotionDetails.pulseColor}`}}
            >
                {emotionDetails.emoji}
           </span>
        </div>

        <h1 className={`mt-8 text-4xl font-bold transition-colors duration-500 ${emotionDetails.color}`}>
          {displayLabel}
        </h1>

        <div className={`mt-4 flex flex-col gap-1 items-center transition-opacity duration-300 ${isSystemRunning ? 'opacity-100' : 'opacity-0'}`}>
             {currentConfidence !== null && (
                 <div className="text-sm font-medium text-gray-600 dark:text-gray-300 bg-white/50 dark:bg-black/20 px-3 py-1 rounded-full">
                     Confidence: {(currentConfidence * 100).toFixed(1)}%
                 </div>
             )}
             {lastUpdate !== null && (
                 <div className="text-xs text-gray-400 dark:text-gray-500">
                     Last updated: {new Date(lastUpdate).toLocaleTimeString()}
                 </div>
             )}
        </div>

        <p className="text-gray-500 dark:text-gray-400 mt-4 max-w-xs">
            {isSystemRunning 
                ? "Listening to Azure emotion stream..." 
                : "System is paused. Press Start to begin."}
        </p>

        {connectionStatus === 'error' && connectionError && (
          <div className="mt-4 p-3 bg-red-100 dark:bg-red-900/50 border border-red-300 dark:border-red-700 rounded-lg text-red-700 dark:text-red-300 text-sm max-w-sm" role="alert">
