// --- Peli Character Component (Virtual Pet) ---
interface PeliProps {
  emotion: string;
  animationClass?: string;
  showParticles?: string;
  customEyes?: string;
  isGlowing?: boolean;
  scale?: number;
  accessories?: 'headphones' | null;
  isDirty?: boolean;
  isWet?: boolean;
  isHungry?: boolean;
  bubbles?: boolean;
}

export const PeliCharacter: React.FC<PeliProps> = ({ 
    emotion, 
    animationClass, 
    showParticles, 
    customEyes, 
    isGlowing, 
    scale = 1, 
    accessories = null,
    isDirty = false,
    isWet = false,
    isHungry = false,
    bubbles = false
}) => {
  const { equippedItems } = useAppContext();

  const traits = useMemo(() => {
    let color = '#FFE8C7';
    let eyes = 'normal';
    let mouth = 'smile';
    let eyebrows = 'neutral';

    const normEmo = emotion.toLowerCase();

    if (['happy', 'excited', 'proud', 'confident'].includes(normEmo)) {
      color = '#fcd34d';
      eyes = 'squint';
      mouth = 'open-smile';
      eyebrows = 'up';
    } else if (['sad', 'lonely'].includes(normEmo)) {
      color = '#93c5fd';
      eyes = 'sad';
      mouth = 'frown';
      eyebrows = 'sad';
    } else if (['angry', 'mad', 'tense'].includes(normEmo)) {
      color = '#f87171';
      eyes = 'angry';
      mouth = 'frown';
      eyebrows = 'angry';
    } else if (['fear', 'scared', 'nervous', 'worried'].includes(normEmo)) {
      color = '#a5b4fc';
      eyes = 'wide';
      mouth = 'wavy';
      eyebrows = 'up';
    } else if (['surprised', 'curious'].includes(normEmo)) {
      color = '#d8b4fe';
      eyes = 'wide';
      mouth = 'o-shape';
      eyebrows = 'up';
    } else if (normEmo === 'disgust') {
      color = '#84cc16';
      eyes = 'squint';
      mouth = 'wavy';
      eyebrows = 'angry';
    } else if (['love', 'grateful', 'relaxed', 'calm'].includes(normEmo)) {
      color = '#f472b6';
      eyes = 'happy-closed';
      mouth = 'smile';
      eyebrows = 'neutral';
    } else if (['sleeping', 'meditating', 'tired'].includes(normEmo)) {
        color = '#a5f3fc';
        eyes = 'happy-closed';
        mouth = 'smile';
        eyebrows = 'neutral';
    } else if (['nature', 'serene', 'bird'].includes(normEmo)) {
        color = '#86efac';
        eyes = 'happy-closed';
        mouth = 'smile';
        eyebrows = 'neutral';
    }

    if (customEyes) eyes = customEyes;
    return { color, eyes, mouth, eyebrows };
  }, [emotion, customEyes]);

  return (
    <div className={`relative w-full h-full shrink-0 flex items-center justify-center transition-all duration-500 ${animationClass}`}>
      {showParticles === 'hearts' && <div className="absolute inset-0 text-4xl animate-ping opacity-50 z-10">❤️</div>}
      {showParticles === 'stars' && <div className="absolute -top-4 -right-4 text-4xl animate-bounce z-10">⭐</div>}
      {showParticles === 'notes' && <div className="absolute -top-4 -left-4 text-4xl animate-pulse z-10">🎵</div>}
      {showParticles === 'bubbles' && <div className="absolute -top-8 left-10 text-3xl animate-bounce z-20">🫧</div>}

      <svg
        viewBox="0 0 200 200"
        className={`w-full h-full transition-all duration-500 ease-in-out ${isGlowing ? 'drop-shadow-[0_0_25px_rgba(255,255,255,0.8)] brightness-110' : 'drop-shadow-2xl'}`}
        style={{ transform: `scale(${scale})` }}
      >
        <path d="M40,160 Q20,100 40,40 Q100,0 160,40 Q180,100 160,160 Q100,190 40,160 Z" fill={traits.color} />
        <ellipse cx="140" cy="60" rx="10" ry="5" fill="white" fillOpacity="0.4" transform="rotate(-45 140 60)" />

        {isDirty && (
          <g fill="#78350f" fillOpacity="0.6">
             <circle cx="60" cy="140" r="8" />
             <circle cx="150" cy="130" r="10" />
             <circle cx="100" cy="50" r="6" />
          </g>
        )}

        {bubbles && (
            <g fill="white" fillOpacity="0.7" stroke="#e0f2fe" strokeWidth="1">
                <circle cx="50" cy="150" r="10" />
                <circle cx="140" cy="140" r="12" />
                <circle cx="90" cy="50" r="8" />
            </g>
        )}

        {equippedItems.clothes === 'cloth_tie' && (
             <g transform="translate(100, 140)">
                 <path d="M0,0 L15,-8 L15,8 Z M0,0 L-15,-8 L-15,8 Z" fill="#ef4444" />
                 <circle cx="0" cy="0" r="4" fill="#b91c1c" />
             </g>
        )}

        <g transform="translate(0, 10)">
           {traits.eyes === 'normal' && (
             <g>
               <ellipse cx="70" cy="80" rx="13" ry="15" fill="#1e293b" />
               <circle cx="75" cy="74" r="4.5" fill="white" />
             </g>
           )}
           {traits.eyes === 'wide' && (
             <g>
               <circle cx="70" cy="80" r="16" fill="white" stroke="#1e293b" strokeWidth="2.5" />
               <circle cx="70" cy="80" r="7" fill="#1e293b" />
             </g>
           )}
           {traits.eyes === 'squint' && <path d="M55,85 Q70,70 85,85" stroke="#1e293b" strokeWidth="4" fill="none" strokeLinecap="round" />}
           {traits.eyes === 'happy-closed' && <path d="M55,80 Q70,70 85,80" stroke="#1e293b" strokeWidth="4" fill="none" strokeLinecap="round" />}

           <ellipse cx="130" cy="80" rx="13" ry="15" fill="#1e293b" />
        </g>

        <g transform="translate(100, 120)">
           {traits.mouth === 'smile' && <path d="M-25,0 Q0,15 25,0" stroke="#1e293b" strokeWidth="4" fill="none" strokeLinecap="round" />}
           {traits.mouth === 'open-smile' && <path d="M-25,-5 Q0,25 25,-5 Z" fill="white" stroke="#1e293b" strokeWidth="3" strokeLinecap="round" />}
        </g>

        {equippedItems.hat === 'hat_cap' && (
             <g>
                 <path d="M50,45 Q100,0 150,45" fill="#2563eb" />
             </g>
        )}

        {accessories === 'headphones' && (
          <g>
            <path d="M45,80 Q45,5 100,5 Q155,5 155,80" fill="none" stroke="#374151" strokeWidth="10" strokeLinecap="round" />
            <rect x="30" y="70" width="25" height="50" rx="8" fill="#4b5563" />
            <rect x="145" y="70" width="25" height="50" rx="8" fill="#4b5563" />
          </g>
        )}
      </svg>
    </div>
  );
};

