                {['Happy', 'Sad', 'Angry', 'Surprised'].map(e => (
                    <button key={e} onClick={() => { if(e===emo) onComplete(); else setEmo('Sad'); }} className="bg-white/20 p-4 rounded-xl font-bold">{e}</button>
                ))}
            </div>
        </div>
    );
};

const GenericTimer: React.FC<{ activity: Activity; onComplete: () => void }> = ({ activity, onComplete }) => {
  const [timeLeft, setTimeLeft] = useState(activity.duration);
  useEffect(() => {
    if (timeLeft <= 0) { onComplete(); return; }
    const t = setInterval(() => setTimeLeft(p => p - 1), 1000);
    return () => clearInterval(t);
  }, [timeLeft, onComplete]);
  return (
    <div className="flex flex-col items-center justify-center py-8">
      <h2 className="text-3xl font-bold">{activity.name}</h2>
      <p className="text-7xl font-mono font-bold my-12">{timeLeft}s</p>
      <div className="w-full h-4 bg-white/20 rounded-full overflow-hidden">
        <div className="h-full bg-white transition-all" style={{width: `${((activity.duration - timeLeft)/activity.duration)*100}%`}}></div>
      </div>
    </div>
  );
};

const ActivityModal: React.FC<ActivityModalProps> = ({ activity, onClose, onOpenShop }) => {
  const { addActivityLog, earnDrachma } = useAppContext();
  const [isComplete, setIsComplete] = useState(false);

  const handleComplete = () => {
    if (!isComplete) {
      setIsComplete(true);
      addActivityLog(activity.name);
      earnDrachma(activity.reward);
      setTimeout(onClose, 2000);
    }
  };

  const renderContent = () => {
    if (isComplete) return <div className="animate-bounce text-4xl font-bold mt-20">Great Job! 🌟</div>;
    switch (activity.name) {
      case 'Play Music': return <MusicPlayer onComplete={handleComplete} />;
      case 'Tell Story': return <StoryMode onComplete={handleComplete} />;
      case 'Exercise': return <BrainExercise onComplete={handleComplete} />;
      default: return <GenericTimer activity={activity} onComplete={handleComplete} />;
    }
