  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/60 backdrop-blur-sm">
      <div className={`relative w-full h-full sm:max-w-md flex flex-col p-6 text-white text-center shadow-2xl bg-gradient-to-br ${activity.color} overflow-hidden sm:rounded-3xl`}>
