import React, { useState, useEffect, useRef } from 'react';
import { useAppContext } from '../contexts/AppContext';
import { ChatMessage, Emotion } from '../types';
import { PaperAirplaneIcon } from './Icons';
import { GoogleGenAI } from '@google/genai';

const ChatTab: React.FC = () => {
  const { companionName, currentEmotion, userName } = useAppContext();
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [userInput, setUserInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setMessages([
      {
        id: 'welcome',
        text: `Hi ${userName || 'friend'}! I'm ${companionName}. I see you're feeling ${currentEmotion.toLowerCase()} today. How can I support you?`,
        sender: 'companion',
        timestamp: Date.now(),
      }
    ]);
  }, [companionName, userName]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userInput.trim() || isTyping) return;

    const userText = userInput.trim();
    setUserInput('');

    const newUserMessage: ChatMessage = {
      id: Date.now().toString(),
      text: userText,
      sender: 'user',
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, newUserMessage]);
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userText,
        config: {
          systemInstruction: `You are ${companionName}, a supportive AI companion for a user named ${userName}. 
          The user is currently feeling ${currentEmotion}. 
          Provide short, encouraging, and empathetic responses (max 2 sentences). 
          Suggest activities like meditation, music, or exercise if they seem stressed.`,
        },
      });

      const companionResponse: ChatMessage = {
        id: (Date.now() + 1).toString(),
        text: response.text || "I'm here for you!",
        sender: 'companion',
        timestamp: Date.now(),
      };
      setMessages(prev => [...prev, companionResponse]);
    } catch (err) {
      console.error("Gemini Error:", err);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="flex flex-col h-full pt-4">
      <div className="flex-1 overflow-y-auto space-y-4 p-4 scrollbar-hide">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-xs p-3 rounded-2xl shadow ${msg.sender === 'user' ? 'bg-indigo-500 text-white rounded-br-none' : 'bg-white dark:bg-gray-700 text-gray-800 dark:text-gray-200 rounded-bl-none'}`}>
              <p>{msg.text}</p>
            </div>
          </div>
        ))}
        {isTyping && <div className="text-xs text-gray-400 italic animate-pulse">Peli is thinking...</div>}
        <div ref={messagesEndRef} />
      </div>

      <form onSubmit={handleSendMessage} className="p-4 flex items-center gap-2 bg-white dark:bg-gray-900 border-t border-gray-100 dark:border-gray-800">
        <input
          type="text"
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)}
          placeholder="Type a message..."
          className="flex-1 p-3 border border-gray-300 dark:border-gray-600 dark:bg-gray-800 dark:text-white rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none transition"
        />
        <button type="submit" className="bg-indigo-500 text-white p-3 rounded-xl hover:bg-indigo-600 transition-colors shadow">
          <PaperAirplaneIcon className="w-6 h-6" />
        </button>
      </form>
    </div>
  );
};

